-- 宾馆房间预订与管理系统 建库脚本（含演示数据）
-- 由 db 生成脚本产出，字符集 utf8mb4

CREATE DATABASE IF NOT EXISTS hotel DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE hotel;

SET NAMES utf8mb4;

DROP TABLE IF EXISTS reservation;
DROP TABLE IF EXISTS room;
DROP TABLE IF EXISTS room_type;
DROP TABLE IF EXISTS `user`;

CREATE TABLE `user` (
  id INT PRIMARY KEY AUTO_INCREMENT,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(100) NOT NULL,
  real_name VARCHAR(50),
  phone VARCHAR(20),
  gender VARCHAR(10),
  role VARCHAR(10) NOT NULL DEFAULT 'USER',
  created_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE room_type (
  id INT PRIMARY KEY AUTO_INCREMENT,
  name VARCHAR(50) NOT NULL,
  price DECIMAL(10,2) NOT NULL,
  capacity INT NOT NULL,
  bed_type VARCHAR(50),
  area INT,
  amenities VARCHAR(255),
  description VARCHAR(500),
  image VARCHAR(100),
  created_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE room (
  id INT PRIMARY KEY AUTO_INCREMENT,
  room_no VARCHAR(10) NOT NULL UNIQUE,
  type_id INT NOT NULL,
  floor INT NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE',
  note VARCHAR(200),
  CONSTRAINT fk_room_type FOREIGN KEY (type_id) REFERENCES room_type(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE reservation (
  id INT PRIMARY KEY AUTO_INCREMENT,
  order_no VARCHAR(30) NOT NULL UNIQUE,
  user_id INT NOT NULL,
  type_id INT NOT NULL,
  room_id INT,
  checkin_date DATE NOT NULL,
  checkout_date DATE NOT NULL,
  nights INT NOT NULL,
  guest_name VARCHAR(50) NOT NULL,
  guest_phone VARCHAR(20) NOT NULL,
  guest_id_card VARCHAR(20),
  guest_count INT NOT NULL DEFAULT 1,
  total_price DECIMAL(10,2) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'RESERVED',
  remark VARCHAR(255),
  created_at DATETIME NOT NULL,
  CONSTRAINT fk_res_user FOREIGN KEY (user_id) REFERENCES `user`(id),
  CONSTRAINT fk_res_type FOREIGN KEY (type_id) REFERENCES room_type(id),
  CONSTRAINT fk_res_room FOREIGN KEY (room_id) REFERENCES room(id),
  INDEX idx_room_date (room_id, checkin_date, checkout_date),
  INDEX idx_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

